reportText:
{
  "findings": [
    {
      "file": "src/api.js",
      "what": "请求的是 /api/v1/users/:id，但 routes.js 中只注册了 /api/v2/users/:id，调用了不存在的 v1 接口（跨文件版本不一致）。"
    },
    {
      "file": "src/money.js",
      "what": "sameAmount 用 === 直接比较浮点金额，相等金额会因浮点精度误差被误判为不等（应比较差值阈值或转整数分比较）。"
    },
    {
      "file": "src/reader.js",
      "what": "openSync 打开的文件描述符在读取后未调用 closeSync 关闭，造成文件描述符泄漏。"
    },
    {
      "file": "src/stats.js",
      "what": "maxOf 的循环条件 i <= arr.length 造成越界访问 arr[arr.length]，应为 i < arr.length（off-by-one）。"
    }
  ]
}
